/* BASE PAINEL - MODELO: a lista de contas bancarias (banco|conta separados por virgula) fica em dados/uau/contas_consulta29.txt, fora do repositorio; python -m financeiro.montar_sql gera dados/uau/sql_base_painel_completo.sql, que e o texto a colar no UAU.  derivado da consulta geral 843 (Movimentacao Financeira Geral). Empresas 1-45 sem PF (4,34-38); todas as contas bancarias; todos os servicos. Parametros: <DataInicio>, <DataTermino>, <Relatorio> (0=a pagar+a receber por vencimento; 1=pagos+recebidos por data de pagamento; 2=pagos+recebidos por conciliacao). Criado em 01/11/2026. 02/11/2026: incluidas 3 contas Caixa encerradas nas 3 listas de contas; gravado no UAU em 02/11/2026. v3 (02/11/2026): lado credito das transferencias usa EmpresaCred_Tb e HistLancCred_Tb, para que o recebimento apareca na empresa de destino. */
DECLARE @Relatorio INT SET @Relatorio = <Relatorio> /* A Pagar/Receber */ IF @Relatorio = 0 BEGIN SELECT  Movimentacao.Empresa, CAST(Movimentacao.Empresa AS VARCHAR) + ' - ' + UPPER(Empresas.Desc_Emp) [DescEmpresa], Movimentacao.Obra, Movimentacao.Obra + ' - ' + UPPER(Obras.Descr_Obr) [DescObra], Movimentacao.Item, CAST(<DataInicio> AS DATETIME) [Inicio], CAST(<DataTermino> AS DATETIME) [Fim], Movimentacao.CompPl_Des, Movimentacao.Descr_Comp, UPPER( CASE WHEN Nominal.Nome_Pes IS NULL THEN Movimentacao.Nominal ELSE Nominal.Nome_Pes END ) [Nominal], '' [BancoConta], UPPER(ISNULL( CASE WHEN Fornecedor.Nome_Pes IS NULL THEN CAST(Movimentacao.Fornecedor AS VARCHAR) ELSE Fornecedor.Nome_Pes END, '')  ) [Fornecedor], ISNULL(  CASE WHEN(Nominal.Nome_Pes IS NULL) THEN CASE Fornecedor.Tipo_Pes WHEN 0 THEN SUBSTRING(REPLICATE('0',11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 1, 3) + '.' + SUBSTRING(REPLICATE('0',11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 4, 3) + '.' + SUBSTRING(REPLICATE('0',11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 7, 3) + '-' + SUBSTRING(REPLICATE('0',11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 10,2) WHEN 1 THEN SUBSTRING(REPLICATE('0',14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 1, 2) + '.' + SUBSTRING(REPLICATE('0',14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 3, 3) + '.' + SUBSTRING(REPLICATE('0',14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 6, 3) + '/' + SUBSTRING(REPLICATE('0',14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 9,4 ) + '-' + SUBSTRING(REPLICATE('0',14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 13,2) END ELSE CASE Nominal.Tipo_Pes WHEN 0 THEN SUBSTRING(REPLICATE('0',11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 1, 3) + '.' + SUBSTRING(REPLICATE('0',11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 4, 3) + '.' + SUBSTRING(REPLICATE('0',11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 7, 3) + '-' + SUBSTRING(REPLICATE('0',11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 10,2) WHEN 1 THEN SUBSTRING(REPLICATE('0',14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 1, 2) + '.' + SUBSTRING(REPLICATE('0',14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 3, 3) + '.' + SUBSTRING(REPLICATE('0',14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 6, 3) + '/' + SUBSTRING(REPLICATE('0',14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 9,4 ) + '-' + SUBSTRING(REPLICATE('0',14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 13,2) END END, ''  ) [CNPJ], Movimentacao.NF, Movimentacao.Valor, Movimentacao.Chave_Venda, Movimentacao.Vencimento, Movimentacao.Banco, Movimentacao.Agencia, Movimentacao.Conta, Movimentacao.Cheque, Movimentacao.Emissao, Movimentacao.Natureza, Movimentacao.DtNF, Movimentacao.Processo, Movimentacao.Chave1, Movimentacao.Origem, Movimentacao.ValorNF, UPPER(Movimentacao.TipoParc) [TipoParc], Movimentacao.BancoConta, Movimentacao.ProdutoPl_Des, ISNULL(CAST(Movimentacao.ProdutoPl_Des AS VARCHAR) + ' - ' + UPPER(PrdSrv.Descricao_Psc), '-3 - INDIRETO') [Produto], 0 [Relatorio], Movimentacao.OC, Movimentacao.Cotacao, NULL [Cap_Des], NULL [DescCap_Des] FROM ( SELECT  Empresa_Des [Empresa], Obra_Des [Obra], ItemPl_Des [Item], CompPl_Des, Descr_Comp, ChqNome_Proc [Nominal], CodForn_Proc [Fornecedor], DocFiscal_Proc [NF], - SUM(  CASE WHEN Tipo = 1 THEN Total ELSE 0 END  ) [Valor], '' [Chave_Venda], DtVencParc_Proc [Vencimento], Banco_Des [Banco], Agencia_Banco [Agencia], ContaCorr_Des [Conta], '' [Cheque], DtPagParc_Proc [Emissao], Codigo_Cmf + ' - ' + Desc_Cmf [Natureza], DtDocFisc_Proc [DtNF], CAST(NumProc_Des AS VARCHAR) [Processo], CAST(CodForn_Proc AS VARCHAR) + '_' + CAST(NumProc_Des AS VARCHAR) + '_' + CAST(NumParc_Des AS VARCHAR) [Chave1], 'CONTAS A PAGAR' [Origem], VlDocFisc_Proc [ValorNF], '' [TipoParc], CAST(Banco_Des AS VARCHAR) + '|' + ContaCorr_Des [BancoConta], ProdutoPl_Des, OC, Cotacao FROM ( SELECT  Empresa_Des, Obra_Des, ItemPl_Des, CompPl_Des, SUM(TotalLiq_Des) [Total], NumProc_Des, NumParc_Des, Banco_Des, ContaCorr_Des, 1 [Tipo], ProdutoPl_Des FROM VwDesembolsoAPagar GROUP BY Empresa_Des, Obra_Des, ItemPl_Des, CompPl_Des, NumProc_Des, NumParc_Des, Banco_Des, ContaCorr_Des, ProdutoPl_Des ) [Dados] INNER JOIN ( SELECT DISTINCT Parc_Proc.Num_Proc, Parc_Proc.Empresa_Proc, Parc_Proc.NumParc_Proc, Parc_Proc.Obra_Proc, Parc_Proc.Conta_Proc, Parc_Proc.DtPagParc_Proc, Parc_Proc.VlDocFisc_Proc, Parc_Proc.ChqNome_Proc, Parc_Proc.ObraFisc_Proc, Parc_Proc.DtDocFisc_Proc, Parc_Proc.DocFiscal_Proc, Parc_Proc.CategMovFin_Proc, Parc_Proc.DtVencParc_Proc, Parc_Proc.banContParc_Proc, '' [NumChq_Pag], Dados_Proc.CodForn_Proc, Dados_Proc.OrdemCompra_Proc [OC], Dados_Proc.NumCot_Proc [Cotacao], Parc_Proc.StatusParc_Proc FROM Parc_Proc INNER JOIN Dados_Proc ON Parc_Proc.Empresa_Proc = Dados_Proc.Empresa_Proc AND Parc_Proc.Obra_Proc = Dados_Proc.Obra_Proc AND Parc_Proc.Num_Proc = Dados_Proc.Num_Proc ) [Tab] ON Empresa_Des = Empresa_Proc AND NumProc_Des = Num_Proc AND Obra_Des = Obra_Proc AND NumParc_Des = NumParc_Proc LEFT JOIN CCorrente ON Empresa_Des = Empresa_Banco AND Banco_Des = Numero_Banco  AND ContaCorr_Des = Conta_Banco LEFT JOIN CategoriasDeMovFin ON CategMovFin_Proc = Codigo_Cmf LEFT JOIN Composicoes ON CompPl_Des = Composicoes.Cod_Comp WHERE CompPl_Des LIKE '%' AND DtPagParc_Proc BETWEEN <DataInicio> AND <DataTermino> GROUP BY Empresa_Des, Obra_Des, ItemPl_Des, CompPl_Des, CodForn_Proc, Descr_Comp, NumProc_Des, NumParc_Des, DocFiscal_Proc, Banco_Des, ChqNome_Proc, ContaCorr_Des, Agencia_Banco, DtVencParc_Proc, DtPagParc_Proc, Codigo_Cmf, Desc_Cmf, DtDocFisc_Proc, VlDocFisc_Proc, ProdutoPl_Des, OC, Cotacao UNION ALL SELECT  Empresa_Crc [Empresa], Obra_Crc [Obra], '' [Item], CAST(IdProduto AS VARCHAR) [CompPl_Des], DescProduto [Descr_Comp], CAST(Cliente_Prc AS VARCHAR) [Nominal], NULL [Fornecedor], CAST(NumNfAux_Nf AS VARCHAR) [NF], SUM(ValParcela_Crc) * PorcProdVenda [Valor], '' [Chave_Venda], Data_Prc [Vencimento], '' [Banco], '' [Agencia], '' [Conta], '' [Cheque], DataPror_Prc [Emissao], '' [Natureza], DataEmis_Nf [DtNF], CAST(NumVend_Crc AS VARCHAR) + '-' + CAST(NumParc_Crc AS VARCHAR) [Processo], '' [Chave1], 'CONTAS RECEBER' [Origem], ValorTotNota_Nf [ValorNF], COALESCE(Descricao_Par, '') [TipoParc], '0|0', 0 [Produto], NULL, NULL FROM ContasReceberCalc INNER JOIN ContasReceber ON Empresa_Crc = Empresa_Prc AND Obra_Crc = Obra_Prc AND NumVend_Crc = NumVend_Prc AND NumParc_Crc = NumParc_Prc AND Tipo_Crc = Tipo_Prc AND NumParcGer_Crc = NumParcGer_Prc LEFT JOIN Parcelas ON Tipo_Crc = Tipo_Par LEFT JOIN ( SELECT  EmpresaNf_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END [NumNfAux_Nf], ObraVen_Vnv, MAX(DataEmis_Nf) [DataEmis_Nf], NumVen_Vnv, SUM(ValorTotNota_Nf) [ValorTotNota_Nf] FROM NotasFiscais INNER JOIN VinculoNotaVenda ON Empresa_Nf = EmpresaNf_Vnv AND Num_Nf = NumNf_Vnv INNER JOIN (  SELECT  EmpresaNf_Vnv [Empresa], ObraVen_Vnv [Obra], NumVen_Vnv [Venda], COUNT(NumNf_Vnv) [Cont] FROM VinculoNotaVenda GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv ) [NotasVenda] ON Empresa = EmpresaNf_Vnv AND Obra = ObraVen_Vnv AND Venda = NumVen_Vnv GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END ) [NotasF] ON Empresa_Crc = EmpresaNf_Vnv AND NumVend_Crc = NumVen_Vnv AND Obra_Crc = ObraVen_Vnv INNER JOIN (  SELECT  Empresa_Ven, Obra_Ven, Num_Ven, Produto_Itv [IdProduto], Descricao_Psc [DescProduto], ((Qtde_Itv * PrecoProc_Itv) - ValComissaoDir_Itv) / ValorTot_Ven [PorcProdVenda] FROM Vendas INNER JOIN ItensVenda ON Empresa_Ven = Empresa_Itv AND Obra_Ven = Obra_Itv AND Num_Ven = NumVend_Itv INNER JOIN PrdSrv ON NumProd_Psc = Produto_Itv WHERE ValorTot_Ven > 0 ) [ProdVenda] ON Empresa_Crc = Empresa_Ven AND NumVend_Crc = Num_Ven AND Obra_Crc = Obra_Ven WHERE Data_Prc BETWEEN <DataInicio> AND <DataTermino> GROUP BY Empresa_Crc, Obra_Crc, Cliente_Prc, Descricao_Par, Data_Prc, DataPror_Prc, NumVend_Crc, NumParc_Crc, NumNfAux_Nf, IdProduto, DescProduto, PorcProdVenda, NumNfAux_Nf, DataEmis_Nf, ValorTotNota_Nf ) [Movimentacao] LEFT JOIN Pessoas [Nominal] ON CASE WHEN(ISNUMERIC(Movimentacao.Nominal) = 1) THEN CAST(Movimentacao.Nominal AS INT) ELSE NULL END = Nominal.Cod_Pes LEFT JOIN Pessoas [Fornecedor] ON Movimentacao.Fornecedor = Fornecedor.Cod_Pes INNER JOIN (SELECT Empresa_Obr [Empresa], Cod_Obr [Obra] FROM Obras WHERE Empresa_Obr BETWEEN 1 AND 45 AND Empresa_Obr NOT IN (4,34,35,36,37,38)) [EmpresaObra] ON Movimentacao.Empresa = EmpresaObra.Empresa AND Movimentacao.Obra = EmpresaObra.Obra LEFT JOIN PrdSrv ON Movimentacao.ProdutoPl_Des = PrdSrv.NumProd_Psc INNER JOIN Empresas ON Movimentacao.Empresa = Empresas.Codigo_Emp INNER JOIN Obras ON Movimentacao.Empresa = Obras.Empresa_Obr AND Movimentacao.Obra = Obras.Cod_Obr ORDER BY Movimentacao.Empresa, Movimentacao.Obra, Movimentacao.Origem, Movimentacao.Vencimento END ELSE  /* Geral */ IF @Relatorio = 1 BEGIN SELECT  Movimentacao.Empresa, CAST(Movimentacao.Empresa AS VARCHAR) + ' - ' + UPPER(Empresas.Desc_Emp) [DescEmpresa],  Movimentacao.Obra, Movimentacao.Obra + ' - ' + UPPER(Obras.Descr_Obr) [DescObra], Movimentacao.Item, CAST(<DataInicio> AS DATETIME) [Inicio], CAST(<DataTermino> AS DATETIME) [Fim], Movimentacao.CompPl_Des, UPPER(Movimentacao.Descr_Comp) [Descr_Comp], UPPER( CASE WHEN Nominal.Nome_Pes IS NULL THEN Movimentacao.Nominal ELSE Nominal.Nome_Pes END ) [Nominal], '' [BancoConta], UPPER(ISNULL( CASE WHEN Fornecedor.Nome_Pes IS NULL THEN CAST(Movimentacao.Fornecedor AS VARCHAR) ELSE Fornecedor.Nome_Pes END, '')  ) [Fornecedor], ISNULL( CASE WHEN Nominal.Nome_Pes IS NULL THEN CASE Fornecedor.Tipo_Pes WHEN 0 THEN SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 1, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 4, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 7, 3) + '-' + SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 10, 2) WHEN 1 THEN SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 1, 2) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 3, 3) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 6, 3) + '/' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 9, 4) + '-' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 13, 2) END ELSE CASE Nominal.Tipo_Pes WHEN 0 THEN SUBSTRING(REPLICATE('0', 11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 1, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 4, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 7, 3) + '-' + SUBSTRING(REPLICATE('0', 11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 10, 2) WHEN 1 THEN SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 1, 2) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 3, 3) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 6, 3) + '/' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 9,4) + '-' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 13, 2) END END, ''  ) [CNPJ], Movimentacao.NF, Movimentacao.Valor, Movimentacao.Chave_Venda, Movimentacao.Vencimento, Movimentacao.Banco, Movimentacao.Agencia, Movimentacao.Conta, Movimentacao.Cheque, Movimentacao.Emissao, UPPER(Movimentacao.Natureza) [Natureza], Movimentacao.DtNF, Movimentacao.Processo, Movimentacao.Chave1, Movimentacao.Origem, Movimentacao.ValorNF, UPPER(Movimentacao.TipoParc) [TipoParc], Movimentacao.BancoConta, Movimentacao.ProdutoPl_Des, COALESCE(CAST(Movimentacao.ProdutoPl_Des AS VARCHAR) + ' - ' + UPPER(PrdSrv.Descricao_Psc), '-3 - INDIRETO') [Produto], 1 [Relatorio], Movimentacao.OC, Movimentacao.Cotacao, NULL [Cap_Des], NULL [DescCap_Des] FROM ( SELECT  Empresa_Des [Empresa], Obra_Des [Obra], ItemPl_Des [Item], CompPl_Des, Descr_Comp, Nominal, Fornecedor, NF,  - SUM( CASE WHEN Tipo = 1 THEN Total ELSE 0 END ) [Valor], '' [Chave_Venda], Vencimento, Banco, Agencia, Conta, Cheque, Emissao, Natureza, DtNF, CAST(Processo AS VARCHAR) [Processo], CAST(Fornecedor AS VARCHAR) + '_' + CAST(Processo AS VARCHAR) + '_' + CAST(Parcela AS VARCHAR) [Chave1], 'CONTAS PAGAS' [Origem], Dados.ValorNF, '' [TipoParc], CAST(Banco AS VARCHAR) + '|' + Conta [BancoConta], ProdutoPl_Des, OC, Cotacao FROM ( SELECT  Empresa_Des, Obra_Des, ItemPl_Des, CompPl_Des, InsumoPl_Des, CodForn_Pag [Fornecedor], SUM(TotalLiq_Des) [Total], NumProc_Pag [Processo], NumParc_Pag [Parcela], DataEmissao_Pag [DataPg], NumFiscal_Pag [NF], BancoProc_Pag [Banco], ChqNome_Pag [Nominal], Conta_Pag [Conta], Agencia_Banco [Agencia], NumChq_Pag [Cheque], DataVencParc_Pag [Vencimento], DataEmissao_Pag [Emissao], 1 [Tipo], Codigo_Cmf + ' - ' + Desc_Cmf [Natureza], DtDocFisc_Pag [DtNF], DocFiscal_Pag [ValorNF], ProdutoPl_Des, OC, Cotacao FROM vwDesembolsoPago INNER JOIN ( SELECT DISTINCT NumProc_Pag, Empresa_Pag, NumParc_Pag, ObraProc_Pag, CodForn_Pag, Conta_Pag, DataEmissao_Pag, DocFiscal_Pag, ChqNome_Pag, ObrFiscal_Pag, DtDocFisc_Pag, NumFiscal_Pag, CategMovFin_Pag, DataVencParc_Pag, BancoProc_Pag, NumChq_Pag, OrdemCompra_Pag [OC], NumCot_Pag [Cotacao] FROM ContasPagas ) [ContasPagas] ON Empresa_Des = Empresa_Pag AND NumProc_Des = NumProc_Pag AND Obra_Des = ObraProc_Pag AND NumParc_Des = NumParc_Pag AND Banco_Des = BancoProc_Pag LEFT JOIN CCorrente ON Empresa_Pag = Empresa_Banco AND BancoProc_Pag = Numero_Banco AND Conta_Pag = Conta_Banco LEFT JOIN CategoriasDeMovFin ON CategMovFin_Pag = Codigo_Cmf WHERE CompPl_Des LIKE '%' AND DataEmissao_Pag BETWEEN <DataInicio> AND <DataTermino> AND StatusParc_Des = 2 GROUP BY Empresa_Des, Obra_Des, ItemPl_Des, CompPl_Des, InsumoPl_Des, DataEmissao_Pag, NumProc_Pag, NumParc_Pag, CodForn_Pag, NumFiscal_Pag, BancoProc_Pag, ChqNome_Pag, Conta_Pag, Agencia_Banco, NumChq_Pag, DataVencParc_Pag, DataEmissao_Pag, Codigo_Cmf, Desc_Cmf, DtDocFisc_Pag, DocFiscal_Pag, ProdutoPl_Des, OC, Cotacao ) [Dados] LEFT JOIN Composicoes ON CompPl_Des = Cod_Comp LEFT JOIN Insumos ON Empresa_Des = Empresa_Ins AND Obra_Des = Obra_Ins AND InsumoPl_Des = Cod_Ins GROUP BY Empresa_Des, Obra_Des, ItemPl_Des, CompPl_Des, Fornecedor, Descr_Comp, InsumoPl_Des, Insumos.Descr_Ins, Processo, Parcela, DataPg, NF, Banco, Nominal, Conta, Agencia, Cheque, Vencimento, Emissao, Natureza, DtNF, ValorNF, ProdutoPl_Des, OC, Cotacao UNION ALL SELECT  Empresa_Es [Empresa], Obra_Es [Obra], '' [Item], '' [CompPl_Des], '' [Descr_Comp], HistLanc_Es [Nominal], NULL [Fornecedor], NumDoc_Es [NF], CASE EntSai_Es WHEN 0 THEN 1 WHEN 1 THEN -1 END * Valor_Es [Valor], '' [Chave_Venda], Data_Es [Vencimento], Banco_Es [Banco], Agencia_Banco [Agencia], Conta_Es [Conta], '' [Cheque], Data_Es [Emissao], '' [Natureza], NULL [DtNF], '' [Processo], '' [Chave1], 'CONTROLE FINANCEIRO' [Origem], 0 [ValorNF], '' [TipoParc], CAST(Banco_Es AS VARCHAR) + '|' + CAST(Conta_Es AS VARCHAR) [BancoConta], 0 [Produto], NULL, NULL FROM EntSaiEmpAplic INNER JOIN CCorrente ON Empresa_Es = Empresa_Banco AND Conta_Es = Conta_Banco AND Banco_Es = Numero_Banco WHERE Data_Es BETWEEN <DataInicio> AND <DataTermino> UNION ALL SELECT  Empresa_Tb [Empresa], 'DIVERSAS' [Obra], '' [Item], '' [CompPl_Des], '' [Descr_Comp], HistLanc_Tb [Nominal], NULL [Fornecedor], NumDoc_Tb [NF], - Valor_Tb [Valor], '' [Chave_Venda], Data_Tb [Vencimento], BcoDeb_Tb [Banco], Agencia_Banco [Agencia], Contadeb_Tb [Conta], '' [Cheque], Data_Tb [Emissão], '' [Natureza], NULL [DtNF], '' [Processo], '' [Chave1], 'TRANSFERÊNCIA' [Origem], 0 [ValorNF], '' [TipoParc], CAST(BcoDeb_Tb AS VARCHAR) + '|' + CAST(Contadeb_Tb AS VARCHAR) [BancoConta], 0 [Produto], NULL, NULL FROM TransfBco INNER JOIN CCorrente ON Empresa_Tb = Empresa_Banco AND Contadeb_Tb = Conta_Banco AND Bcodeb_Tb = Numero_Banco WHERE Data_Tb BETWEEN <DataInicio> AND <DataTermino> UNION ALL  SELECT  EmpresaCred_Tb [Empresa], 'DIVERSAS' [Obra], '' [Item], '' [CompPl_Des], '' [Descr_Comp], COALESCE(NULLIF(HistLancCred_Tb, ''), HistLanc_Tb) [Nominal], NULL [Fornecedor], NumDoc_Tb [NF], Valor_Tb [Valor], '' [Chave_Venda], Data_Tb [Vencimento], BcoCred_Tb [Banco], Agencia_Banco [Agencia], ContaCred_Tb [Conta], '' [Cheque], Data_Tb [Emissão], '' [Natureza], NULL [DtNF], '' [Processo], '' [Chave1], 'TRANSFERÊNCIA' [Origem], 0 [ValorNF], '' [TipoParc], CAST(BcoCred_Tb AS VARCHAR) + '|' + CAST(ContaCred_Tb AS VARCHAR) [BancoConta], 0 [Produto], NULL, NULL FROM TransfBco INNER JOIN CCorrente ON EmpresaCred_Tb = Empresa_Banco AND Contacred_Tb = Conta_Banco AND Bcocred_Tb = Numero_Banco WHERE Data_Tb BETWEEN <DataInicio> AND <DataTermino> UNION ALL SELECT  Empresa_Rec [Empresa], Obra_Rec [Obra], '' [Item], CAST(IdProduto AS VARCHAR) [CompPl_Des], DescProduto [Descr_Comp], CAST(Cliente_Rec AS VARCHAR) [Nominal], NULL [Fornecedor], CAST(NumNfAux_Nf AS VARCHAR) [NF], SUM(PercentValor_Rpd) * PorcProdVenda [Valor], CAST(NumCont_Rpd AS VARCHAR) + '_' + CAST(Tipo_Rpg AS VARCHAR) + '_' + CAST(NumReceb_Rpg AS VARCHAR) [Chave_Venda], DataVenci_Rec [Vencimento], BancoDep_Rpg [Banco], AgenciaDep_Rpg [Agencia], ContaDep_Rpg [Conta], '' [Cheque], Data_Rec [Emissao], '' [Natureza], DataEmis_Nf [DtNF], CAST(NumVend_Rec AS VARCHAR) + '-' + CAST(NumParc_Rec AS VARCHAR) [Processo], '' [Chave1], 'RECEBIDAS' [Origem], ValorTotNota_Nf [ValorNF], COALESCE(Descricao_Par, '') [TipoParc], CAST(BancoDep_Rpg AS VARCHAR) + '|' + CAST(ContaDep_Rpg AS VARCHAR), 0 [Produto], NULL, NULL FROM Recebidas INNER JOIN RecebePgtoDiv ON Empresa_Rec = Empresa_Rpd AND NumVend_Rec = NumVend_Rpd AND Obra_Rec = Obra_Rpd AND NumParc_Rec = NumParc_Rpd AND ParcType_Rec = ParcType_Rpd AND Tipo_Rec = Tipo_Rpd AND NumParcGer_Rec = NumParcGer_Rpd INNER JOIN RecebePgto ON Empresa_Rpd = Empresa_Rpg AND NumReceb_Rpd = NumReceb_Rpg AND NumCont_Rpd = NumCont_Rpg AND TipoRpg_Rpd = Tipo_Rpg INNER JOIN Bancos ON BancoDep_Rpg = Numero_Banco LEFT JOIN Parcelas ON Tipo_Rec = Tipo_Par LEFT JOIN ( SELECT  EmpresaNf_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END [NumNfAux_Nf], ObraVen_Vnv, MAX(DataEmis_Nf) [DataEmis_Nf], NumVen_Vnv, SUM(ValorTotNota_Nf) [ValorTotNota_Nf] FROM NotasFiscais INNER JOIN VinculoNotaVenda ON Empresa_Nf = EmpresaNf_Vnv AND Num_Nf = NumNf_Vnv INNER JOIN ( SELECT  EmpresaNf_Vnv [Empresa], ObraVen_Vnv [Obra], NumVen_Vnv [Venda], COUNT(NumNf_Vnv) [Cont] FROM VinculoNotaVenda GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv ) [NotasVenda] ON Empresa = EmpresaNf_Vnv AND Obra = ObraVen_Vnv AND Venda = NumVen_Vnv GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END ) [NotasF] ON EmpresaNf_Vnv = Empresa_Rec AND NumVen_Vnv = NumVend_Rec AND ObraVen_Vnv = Obra_Rec INNER JOIN ( SELECT  Empresa_VRec, Obra_VRec, Num_VRec, Produto_Itr [IdProduto], Descricao_Psc [DescProduto], ((Qtde_Itr * PrecoProc_Itr) - ValComissaoDir_Itr) / ValorTot_VRec [PorcProdVenda] FROM VendasRecebidas INNER JOIN ItensRecebidas ON Empresa_VRec = Empresa_Itr AND Obra_VRec = Obra_Itr AND Num_VRec = NumVend_Itr INNER JOIN PrdSrv ON Produto_Itr = NumProd_Psc WHERE ValorTot_VRec > 0 ) [ProdVenda] ON Empresa_Rec = Empresa_VRec AND NumVend_Rec = Num_VRec AND Obra_Rec = Obra_VRec WHERE Data_Rec BETWEEN <DataInicio> AND <DataTermino> GROUP BY Empresa_Rec, Obra_Rec, Cliente_Rec, NumCont_Rpd, Tipo_Rpg, NumReceb_Rpg, DataVenci_Rec, BancoDep_Rpg, AgenciaDep_Rpg, ContaDep_Rpg, Data_Rec, NumVend_Rec, NumParc_Rec, Descricao_Par, NumNfAux_Nf, IdProduto, DescProduto, PorcProdVenda, NumNfAux_Nf, DataEmis_Nf, ValorTotNota_Nf ) [Movimentacao] LEFT JOIN Pessoas [Nominal] ON CASE WHEN(ISNUMERIC(Movimentacao.Nominal) = 1) THEN CAST(Movimentacao.Nominal AS INT) ELSE NULL END = Nominal.Cod_Pes LEFT JOIN Pessoas [Fornecedor] ON Movimentacao.Fornecedor = Fornecedor.Cod_Pes INNER JOIN Fn_SplitForTable('<<LISTA_CONTAS>>',',') [BancoConta] ON Movimentacao.BancoConta = BancoConta.Item INNER JOIN ( SELECT DISTINCT Empresa [Emp], 'DIVERSAS' [Obr] FROM (SELECT Empresa_Obr [Empresa], Cod_Obr [Obra] FROM Obras WHERE Empresa_Obr BETWEEN 1 AND 45 AND Empresa_Obr NOT IN (4,34,35,36,37,38)) [LEO] UNION SELECT Empresa [Emp], Obra [Obr] FROM (SELECT Empresa_Obr [Empresa], Cod_Obr [Obra] FROM Obras WHERE Empresa_Obr BETWEEN 1 AND 45 AND Empresa_Obr NOT IN (4,34,35,36,37,38)) [LEO] ) [EmpObr] ON Movimentacao.Empresa = EmpObr.Emp AND Movimentacao.Obra = EmpObr.Obr LEFT JOIN PrdSrv ON Movimentacao.ProdutoPl_Des = PrdSrv.NumProd_Psc LEFT JOIN Empresas ON Movimentacao.Empresa = Empresas.Codigo_Emp LEFT JOIN Obras ON Movimentacao.Empresa = Obras.Empresa_Obr AND Movimentacao.Obra = Obras.Cod_Obr ORDER BY Movimentacao.Empresa, Movimentacao.Obra, Movimentacao.Origem, Movimentacao.Vencimento END ELSE  /* CONCILIADO */ IF @Relatorio = 2 BEGIN  SELECT  Movimentacao.Empresa, CAST(Movimentacao.Empresa AS VARCHAR) + ' - ' + UPPER(Empresas.Desc_Emp) [DescEmpresa], Movimentacao.Obra, Movimentacao.Obra + ' - ' + UPPER(Obras.Descr_Obr) [DescObra], Movimentacao.Item, CAST(<DataInicio> AS DATETIME) [Inicio], CAST(<DataTermino> AS DATETIME) [Fim], Movimentacao.CompPl_Des, UPPER(Movimentacao.Descr_Comp) [Descr_Comp], UPPER( CASE WHEN Nominal.Nome_Pes IS NULL THEN Movimentacao.Nominal ELSE Nominal.Nome_Pes END ) [Nominal], '' [BancoConta], UPPER(ISNULL( CASE WHEN Fornecedor.Nome_Pes IS NULL THEN CAST(Movimentacao.Fornecedor AS VARCHAR) ELSE Fornecedor.Nome_Pes END, '')  ) [Fornecedor], ISNULL( CASE WHEN Nominal.Nome_Pes IS NULL THEN CASE Fornecedor.Tipo_Pes WHEN 0 THEN SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 1, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 4, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 7, 3) + '-' + SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 10, 2) WHEN 1 THEN SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 1, 2) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 3, 3) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 6, 3) + '/' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 9,4 ) + '-' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 13,2) END ELSE CASE Nominal.Tipo_Pes WHEN 0 THEN SUBSTRING(REPLICATE('0', 11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 1, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 4, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 7, 3) + '-' + SUBSTRING(REPLICATE('0', 11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 10,2) WHEN 1 THEN SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 1, 2) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 3, 3) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 6, 3) + '/' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 9,4 ) + '-' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 13,2) END END, ''  ) [CNPJ], Movimentacao.NF, Movimentacao.Valor, Movimentacao.Chave_Venda, Movimentacao.Vencimento, Movimentacao.Banco, Movimentacao.Agencia, Movimentacao.Conta, Movimentacao.Cheque, Movimentacao.Emissao, UPPER(Movimentacao.Natureza) [Natureza], Movimentacao.DtNF, Movimentacao.Processo, Movimentacao.Chave1, Movimentacao.Origem, Movimentacao.ValorNF, UPPER(Movimentacao.TipoParc) [TipoParc], Movimentacao.BancoConta, Movimentacao.ProdutoPl_Des, COALESCE(CAST(Movimentacao.ProdutoPl_Des AS VARCHAR) + ' - ' + UPPER(PrdSrv.Descricao_Psc), '-3 - INDIRETO') [Produto], 2 [Relatorio], Movimentacao.OC, Movimentacao.Cotacao, Movimentacao.Cap_Des, UPPER(Movimentacao.DescCap_Des) [DescCap_Des] FROM ( SELECT  Empresa_Des [Empresa], Obra_Des [Obra], ItemPl_Des [Item], CompPl_Des, DescCompPl_Des [Descr_Comp], NominalProc_Des [Nominal], CodForn_Des [Fornecedor], DocFiscal_Des [NF], - SUM(TotalLiq_Des) [Valor], '' [Chave_Venda], DataVencParc_Pag [Vencimento], Banco_Des [Banco], Agencia_Banco [Agencia], ContaCorr_Des [Conta], NumCheque_Des [Cheque], Data_Doc [Emissao], Codigo_Cmf + ' - ' + Desc_Cmf [Natureza], DtDocFisc_Pag [DtNF], CAST(NumProc_Des AS VARCHAR) [Processo], CAST(CodForn_Des AS VARCHAR) + '_' + CAST(NumProc_Des AS VARCHAR) + '_' + CAST(NumParc_Des AS VARCHAR) [Chave1], 'CONTAS PAGAS' [Origem], VlDocFisc_Des [ValorNF], '' [TipoParc], CAST(Banco_Des AS VARCHAR) + '|' + ContaCorr_Des [BancoConta], ProdutoPl_Des, OC, Cotacao, Cap_Des, DescCap_Des FROM vwDesembolso INNER JOIN (SELECT Empresa_Obr [Empresa], Cod_Obr [Obra] FROM Obras WHERE Empresa_Obr BETWEEN 1 AND 45 AND Empresa_Obr NOT IN (4,34,35,36,37,38)) [LEO] ON Empresa_Des = Empresa AND Obra_Des = Obra INNER JOIN ( SELECT DISTINCT NumProc_Pag, Empresa_Pag, NumParc_Pag, ObraProc_Pag, ObrFiscal_Pag, DtDocFisc_Pag, CategMovFin_Pag, DataVencParc_Pag, OrdemCompra_Pag [OC], NumCot_Pag [Cotacao] FROM ContasPagas ) [Tab] ON Empresa_Des = Empresa_Pag AND NumProc_Des = NumProc_Pag AND Obra_Des = ObraProc_Pag AND NumParc_Des = NumParc_Pag INNER JOIN Extrato ON Empresa_Des = Empresa_Doc AND ContaCorr_Des = Conta_Doc AND NumCheque_Des = Numero_Doc AND Banco_Des = Banco_Doc LEFT JOIN CCorrente ON Empresa_Des = Empresa_Banco AND Banco_Des = Numero_Banco AND ContaCorr_Des = Conta_Banco LEFT JOIN CategoriasDeMovFin ON CategMovFin_Pag = Codigo_Cmf WHERE CompPl_Des LIKE '%' AND Data_Doc BETWEEN <DataInicio> AND <DataTermino>  AND Status_Doc = 2 AND StatusParc_Des = 2 GROUP BY Empresa_Des, Obra_Des, ItemPl_Des, CompPl_Des, CodForn_Des, DescCompPl_Des, InsumoPl_Des, NumProc_Des, NumParc_Des, DocFiscal_Des, Banco_Des, NominalProc_Des, ContaCorr_Des, Agencia_Banco, NumCheque_Des, DataVencParc_Pag, Data_Doc, Codigo_Cmf, Desc_Cmf, DtDocFisc_Pag, VlDocFisc_Des, ProdutoPl_Des, OC, Cotacao, Cap_Des, DescCap_Des UNION ALL SELECT  Empresa_Es [Empresa], Obra_Es [Obra], '' [Item], '' [CompPl_Des], '' [Descr_Comp], HistLanc_Es [Nominal], NULL [Fornecedor], NumDoc_Es [NF], CASE EntSai_Es WHEN 0 THEN 1 WHEN 1 THEN -1 END * Valor_Es [Valor], '' [Chave_Venda], Data_Es [Vencimento], Banco_Es [Banco], Agencia_Banco [Agencia], Conta_Es [Conta], '' [Cheque], Data_Es [Emissao], '' [Natureza], NULL [DtNF], '' [Processo], '' [Chave1], 'CONTROLE FINANCEIRO' [Origem], 0 [ValorNF], '' [TipoParc], CAST(Banco_Es AS VARCHAR) + '|' + CAST(Conta_Es AS VARCHAR) [EmpresaObra], 0 [Produto], NULL, NULL, Cap_Es, Desc_CGer FROM EntSaiEmpAplic INNER JOIN CCorrente ON Empresa_Es = Empresa_Banco AND Conta_Es = Conta_Banco AND Banco_Es = Numero_Banco LEFT JOIN Cap ON Cap_Es = Codigo_CGer WHERE Data_Es BETWEEN <DataInicio> AND <DataTermino> UNION ALL SELECT  Empresa_Tb [Empresa], 'DIVERSAS' [Obra], '' [Item], '' [CompPl_Des], '' [Descr_Comp], HistLanc_Tb [Nominal], NULL [Fornecedor], NumDoc_Tb [NF], - Valor_Tb [Valor], '' [Chave_Venda], Data_Tb [Vencimento], BcoDeb_Tb [Banco], Agencia_Banco [Agencia], Contadeb_Tb [Conta], '' [Cheque], Data_Tb [Emissão], '' [Natureza], NULL [DtNF], '' [Processo], '' [Chave1], 'TRANSFERÊNCIA' [Origem], 0 [ValorNF], '' [TipoParc], CAST(BcoDeb_Tb AS VARCHAR) + '|' + CAST(Contadeb_Tb AS VARCHAR) [BancoConta], 0 [Produto], NULL, NULL, NULL, NULL FROM TransfBco INNER JOIN CCorrente  ON Empresa_Tb = Empresa_Banco AND Contadeb_Tb = Conta_Banco AND Bcodeb_Tb = Numero_Banco WHERE Data_Tb BETWEEN <DataInicio> AND <DataTermino> UNION ALL SELECT  EmpresaCred_Tb [Empresa], 'DIVERSAS' [Obra], '' [Item], '' [CompPl_Des], '' [Descr_Comp], COALESCE(NULLIF(HistLancCred_Tb, ''), HistLanc_Tb) [Nominal], NULL [Fornecedor], NumDoc_Tb [NF], Valor_Tb [Valor], '' [Chave_Venda], Data_Tb [Vencimento], BcoCred_Tb [Banco], Agencia_Banco [Agencia], ContaCred_Tb [Conta], '' [Cheque], Data_Tb [Emissão], '' [Natureza], NULL [DtNF], '' [Processo], '' [Chave1], 'TRANSFERÊNCIA' [Origem], 0 [ValorNF], '' [TipoParc], CAST(BcoCred_Tb AS VARCHAR) + '|' + CAST(ContaCred_Tb AS VARCHAR) [BancoConta], 0 [Produto], NULL, NULL, NULL, NULL FROM TransfBco INNER JOIN CCorrente ON EmpresaCred_Tb = Empresa_Banco AND Contacred_Tb = Conta_Banco AND Bcocred_Tb = Numero_Banco WHERE Data_Tb BETWEEN <DataInicio> AND <DataTermino> UNION ALL SELECT  Empresa_Rec [Empresa], Obra_Rec [Obra], '' [Item], CAST(IdProduto AS VARCHAR) [CompPl_Des], DescProduto [Descr_Comp], CAST(Cliente_Rec AS VARCHAR) [Nominal], NULL [Fornecedor], CAST(NumNfAux_Nf AS VARCHAR) [NF], SUM(PercentValor_Rpd) * PorcProdVenda [Valor], CAST(NumCont_Rpd AS VARCHAR) + '_' + CAST(Tipo_Rpg AS VARCHAR) + '_' + CAST(NumReceb_Rpg AS VARCHAR) [Chave_Venda], DataVenci_Rec [Vencimento], BancoDep_Rpg [Banco], AgenciaDep_Rpg [Agencia], ContaDep_Rpg [Conta], '' [Cheque], Data_Doc [Emissao], '' [Natureza], DataEmis_Nf [DtNF], CAST(NumVend_Rec AS VARCHAR) + '-' + CAST(NumParc_Rec AS VARCHAR) [Processo], '' [Chave1], 'RECEBIDAS' [Origem], ValorTotNota_Nf [ValorNF], COALESCE(Descricao_Par, '') [TipoParc], CAST(BancoDep_Rpg AS VARCHAR) + '|' + CAST(ContaDep_Rpg AS VARCHAR), 0 [Produto], NULL, NULL, Cap_Rec, Desc_CGer FROM Recebidas INNER JOIN RecebePgtoDiv ON Empresa_Rec = Empresa_Rpd AND NumVend_Rec = NumVend_Rpd AND Obra_Rec = Obra_Rpd AND NumParc_Rec = NumParc_Rpd AND ParcType_Rec = ParcType_Rpd AND Tipo_Rec = Tipo_Rpd AND NumParcGer_Rec = NumParcGer_Rpd LEFT JOIN Parcelas ON Tipo_Rec = Tipo_Par INNER JOIN RecebePgto ON Empresa_Rpd = Empresa_Rpg AND NumReceb_Rpd = NumReceb_Rpg AND NumCont_Rpd = NumCont_Rpg AND TipoRpg_Rpd = Tipo_Rpg INNER JOIN Extrato ON BancoDep_Rpg = Banco_Doc AND Empresa_Rpg = Empresa_Doc AND ContaDep_Rpg = Conta_Doc AND NumDep_Rpg = Numero_Doc LEFT JOIN Depositos ON Empresa_Dep = Empresa_Rpg AND Numero_Dep = NumDep_Rpg AND Banco_Dep = BancoDep_Rpg AND Conta_Dep = ContaDep_Rpg LEFT JOIN Cap  ON Cap_Rec = Codigo_CGer LEFT JOIN ( SELECT  EmpresaNf_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END [NumNfAux_Nf], ObraVen_Vnv, MAX(DataEmis_Nf) [DataEmis_Nf], NumVen_Vnv, SUM(ValorTotNota_Nf) [ValorTotNota_Nf] FROM NotasFiscais INNER JOIN VinculoNotaVenda ON Empresa_Nf = EmpresaNf_Vnv AND Num_Nf = NumNf_Vnv INNER JOIN ( SELECT  EmpresaNf_Vnv [Empresa], ObraVen_Vnv [Obra], NumVen_Vnv [Venda], COUNT(NumNf_Vnv) [Cont] FROM VinculoNotaVenda GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv ) [NotasVenda] ON Empresa = EmpresaNf_Vnv AND Obra = ObraVen_Vnv AND Venda = NumVen_Vnv GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END ) [NotasF] ON EmpresaNf_Vnv = Empresa_Rec AND NumVen_Vnv = NumVend_Rec AND ObraVen_Vnv = Obra_Rec INNER JOIN ( SELECT  Empresa_VRec, Obra_VRec, Num_VRec, Produto_Itr [IdProduto], Descricao_Psc [DescProduto], ((Qtde_Itr * PrecoProc_Itr) - ValComissaoDir_Itr) / ValorTot_VRec [PorcProdVenda] FROM VendasRecebidas INNER JOIN ItensRecebidas ON Empresa_VRec = Empresa_Itr AND Obra_VRec = Obra_Itr AND Num_VRec = NumVend_Itr INNER JOIN PrdSrv ON NumProd_Psc = Produto_Itr WHERE ValorTot_VRec > 0 ) [ProdVenda] ON Empresa_Rec = Empresa_VRec AND NumVend_Rec = Num_VRec AND Obra_Rec = Obra_VRec WHERE Data_Doc BETWEEN <DataInicio> AND <DataTermino> AND Tipo_Doc = 1 GROUP BY Empresa_Rec, Obra_Rec, Cliente_Rec, NumCont_Rpd, Tipo_Rpg, NumReceb_Rpg, DataVenci_Rec, BancoDep_Rpg, AgenciaDep_Rpg, ContaDep_Rpg, Data_Doc, NumVend_Rec, NumParc_Rec, Descricao_Par, NumNfAux_Nf, IdProduto, DescProduto, PorcProdVenda, NumNfAux_Nf, DataEmis_Nf, ValorTotNota_Nf, Cap_Rec, Desc_CGer ) [Movimentacao] LEFT JOIN Pessoas [Nominal] ON CASE WHEN(ISNUMERIC(Movimentacao.Nominal) = 1) THEN CAST(Movimentacao.Nominal AS INT) ELSE NULL END = Nominal.Cod_Pes LEFT JOIN Pessoas [Fornecedor] ON Movimentacao.Fornecedor = Fornecedor.Cod_Pes INNER JOIN fn_SplitForTable('<<LISTA_CONTAS>>',',') [BancoConta] ON Movimentacao.BancoConta = BancoConta.Item INNER JOIN ( SELECT DISTINCT Empresa [Emp], Obra [Obr] FROM (SELECT Empresa_Obr [Empresa], Cod_Obr [Obra] FROM Obras WHERE Empresa_Obr BETWEEN 1 AND 45 AND Empresa_Obr NOT IN (4,34,35,36,37,38)) [LEO]  UNION  SELECT DISTINCT Empresa [Emp], 'DIVERSAS' [Obr] FROM (SELECT Empresa_Obr [Empresa], Cod_Obr [Obra] FROM Obras WHERE Empresa_Obr BETWEEN 1 AND 45 AND Empresa_Obr NOT IN (4,34,35,36,37,38)) [LEO] ) [EmpObr] ON Movimentacao.Empresa = EmpObr.Emp AND Movimentacao.Obra = EmpObr.Obr LEFT JOIN PrdSrv ON Movimentacao.ProdutoPl_Des = PrdSrv.NumProd_Psc LEFT JOIN Empresas ON Movimentacao.Empresa = Empresas.Codigo_Emp LEFT JOIN Obras ON Movimentacao.Empresa = Obras.Empresa_Obr AND Movimentacao.Obra = Obras.Cod_Obr ORDER BY Movimentacao.Empresa, Movimentacao.Obra, Movimentacao.Origem, Movimentacao.Vencimento END  ELSE  /* A Pagar/Receber/Pago/Recebido/Transferência/Controle Financeiro*/ IF @Relatorio = 3 BEGIN SELECT  Movimentacao.Empresa, CAST(Movimentacao.Empresa AS VARCHAR) + ' - ' + UPPER(Empresas.Desc_Emp) [DescEmpresa], Movimentacao.Obra, Movimentacao.Obra + ' - ' + UPPER(Obras.Descr_Obr) [DescObra], Movimentacao.Item, CAST(<DataInicio> AS DATETIME) [Inicio], CAST(<DataTermino> AS DATETIME) [Fim], Movimentacao.CompPl_Des, Movimentacao.Descr_Comp, UPPER( CASE WHEN Nominal.Nome_Pes IS NULL THEN Movimentacao.Nominal ELSE Nominal.Nome_Pes END ) [Nominal], '' [BancoConta], UPPER(ISNULL( CASE WHEN Fornecedor.Nome_Pes IS NULL THEN CAST(Movimentacao.Fornecedor AS VARCHAR) ELSE Fornecedor.Nome_Pes END, '')  ) [Fornecedor], ISNULL( CASE WHEN Nominal.Nome_Pes IS NULL THEN  CASE Fornecedor.Tipo_Pes WHEN 0 THEN SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 1, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 4, 3) + '.' + SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 7, 3) + '-' + SUBSTRING(REPLICATE('0', 11 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 10, 2) WHEN 1 THEN SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 1, 2) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 3, 3) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 6, 3) + '/' + SUBSTRING(REPLICATE('0', 14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 9, 4 ) + '-' + SUBSTRING(REPLICATE('0',14 - LEN(Fornecedor.CPF_Pes)) + Fornecedor.CPF_Pes, 13, 2) END  ELSE CASE Nominal.Tipo_Pes WHEN 0 THEN SUBSTRING(REPLICATE('0', 11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 1, 3) + '.' + SUBSTRING(REPLICATE('0',11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 4, 3) + '.' + SUBSTRING(REPLICATE('0',11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 7, 3) + '-' + SUBSTRING(REPLICATE('0',11 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 10, 2) WHEN 1 THEN SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 1, 2) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 3, 3) + '.' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 6, 3) + '/' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 9, 4) + '-' + SUBSTRING(REPLICATE('0', 14 - LEN(Nominal.CPF_Pes)) + Nominal.CPF_Pes, 13, 2) END END, ''  ) [CNPJ], Movimentacao.NF, Movimentacao.Valor, Movimentacao.Chave_Venda, Movimentacao.Vencimento, Movimentacao.Banco, Movimentacao.Agencia, Movimentacao.Conta, Movimentacao.Cheque, Movimentacao.Emissao, UPPER(Movimentacao.Natureza) [Natureza], Movimentacao.DtNF, Movimentacao.Processo, Movimentacao.Chave1, Movimentacao.Origem, Movimentacao.ValorNF, UPPER(Movimentacao.TipoParc) [TipoParc], Movimentacao.BancoConta, Movimentacao.ProdutoPl_Des, COALESCE(CAST(Movimentacao.ProdutoPl_Des AS VARCHAR) + ' - ' + UPPER(PrdSrv.Descricao_Psc), '-3 - INDIRETO') [Produto], 3 [Relatorio], Movimentacao.OC, Movimentacao.Cotacao, NULL [Cap_Des], NULL [DescCap_Des] FROM (  SELECT  Empresa_Des [Empresa], Obra_Des [Obra], ItemPl_Des [Item], CompPl_Des, DescCompPl_Des [Descr_Comp], NominalProc_Des [Nominal], CodForn_Des [Fornecedor], DocFiscal_Des [NF], - SUM(TotalLiq_Des) [Valor], '' [Chave_Venda], DataVencParc_Pag [Vencimento], Banco_Des [Banco], Agencia_Banco [Agencia], ContaCorr_Des [Conta], NumCheque_Des [Cheque], DtPgto_Des [Emissao], Codigo_Cmf + ' - ' + Desc_Cmf [Natureza], DtDocFisc_Pag [DtNF], CAST(NumProc_Pag AS VARCHAR) [Processo], CAST(CodForn_Des AS VARCHAR) + '_' + CAST(NumProc_Pag AS VARCHAR) + '_' + CAST(NumParc_Pag AS VARCHAR) [Chave1], CASE WHEN StatusParc_Des = 2 THEN 'CONTAS PAGAS' ELSE 'CONTAS A PAGAR' END [Origem], VlDocFisc_Des [ValorNF], '' [TipoParc], CASE WHEN StatusParc_Des = 2 THEN CAST(Banco_Des AS VARCHAR) + '|' + ContaCorr_Des ELSE '0|0' END [BancoConta], ProdutoPl_Des, OC, Cotacao FROM vwDesembolso INNER JOIN (SELECT Empresa_Obr [Empresa], Cod_Obr [Obra] FROM Obras WHERE Empresa_Obr BETWEEN 1 AND 45 AND Empresa_Obr NOT IN (4,34,35,36,37,38)) [LEO] ON Empresa_Des = Empresa AND Obra_Des = Obra INNER JOIN (  SELECT DISTINCT NumProc_Pag, Empresa_Pag, NumParc_Pag, ObraProc_Pag, ObrFiscal_Pag, DtDocFisc_Pag, CategMovFin_Pag, DataVencParc_Pag, OrdemCompra_Pag [OC], NumCot_Pag [Cotacao] FROM ContasPagas UNION SELECT DISTINCT Parc_Proc.Num_Proc, Parc_Proc.Empresa_Proc, Parc_Proc.NumParc_Proc, Parc_Proc.Obra_Proc, Parc_Proc.ObraFisc_Proc, Parc_Proc.DtDocFisc_Proc, Parc_Proc.CategMovFin_Proc, Parc_Proc.DtVencParc_Proc, Dados_Proc.OrdemCompra_Proc [OC], Dados_Proc.NumCot_Proc [Cotacao] FROM Parc_Proc INNER JOIN Dados_Proc ON Parc_Proc.Empresa_Proc = Dados_Proc.Empresa_Proc AND Parc_Proc.Obra_Proc = Dados_Proc.Obra_Proc AND Parc_Proc.Num_Proc = Dados_Proc.Num_Proc WHERE Parc_Proc.StatusParc_Proc <> 2 ) [Tab] ON Empresa_Des = Empresa_Pag AND NumProc_Des = NumProc_Pag AND Obra_Des = ObraProc_Pag AND NumParc_Des = NumParc_Pag LEFT JOIN CCorrente ON Empresa_Des = Empresa_Banco AND Banco_Des = Numero_Banco AND ContaCorr_Des = Conta_Banco LEFT JOIN CategoriasDeMovFin ON CategMovFin_Pag = Codigo_Cmf WHERE CompPl_Des LIKE '%' AND DtPgto_Des BETWEEN <DataInicio> AND <DataTermino> GROUP BY Empresa_Des, Obra_Des, ItemPl_Des, CompPl_Des, DescCompPl_Des, DtPgto_Des, NumProc_Pag, NumParc_Pag, CodForn_Des, DocFiscal_Des, Banco_Des, NominalProc_Des, ContaCorr_Des, Agencia_Banco, NumCheque_Des, DataVencParc_Pag, DtPgto_Des, Codigo_Cmf, Desc_Cmf, DtDocFisc_Pag, VlDocFisc_Des, ProdutoPl_Des, OC, Cotacao, StatusParc_Des UNION ALL SELECT  Empresa_Es [Empresa], Obra_Es [Obra], '' [Item], '' [CompPl_Des], '' [Descr_Comp], HistLanc_Es [Nominal], NULL [Fornecedor], NumDoc_Es [NF], CASE EntSai_Es WHEN 0 THEN 1 WHEN 1 THEN -1 END * Valor_Es [Valor], '' [Chave_Venda], Data_Es [Vencimento], Banco_Es [Banco], Agencia_Banco [Agencia], Conta_Es [Conta], '' [Cheque], Data_Es [Emissao], '' [Natureza], NULL [DtNF], '' [Processo], '' [Chave1], 'CONTROLE FINANCEIRO' [Origem], 0 [ValorNF], '' [TipoParc], CAST(Banco_Es AS VARCHAR) + '|' + CAST(Conta_Es AS VARCHAR) [BancoConta], 0 [Produto], NULL, NULL FROM EntSaiEmpAplic INNER JOIN CCorrente ON Empresa_Es = Empresa_Banco AND Conta_Es = Conta_Banco AND Banco_Es = Numero_Banco WHERE Data_Es BETWEEN <DataInicio> AND <DataTermino> UNION ALL SELECT  Empresa_Tb [Empresa], 'DIVERSAS' [Obra], '' [Item], '' [CompPl_Des], '' [Descr_Comp], HistLanc_Tb [Nominal], NULL [Fornecedor], NumDoc_Tb [NF], - Valor_Tb [Valor], '' [Chave_Venda], Data_Tb [Vencimento], BcoDeb_Tb [Banco], Agencia_Banco [Agencia], ContaDeb_Tb [Conta], '' [Cheque], Data_Tb [Emissão], '' [Natureza], NULL [DtNF], '' [Processo], '' [Chave1], 'TRANSFERÊNCIA' [Origem], 0 [ValorNF], '' [TipoParc], CAST(BcoDeb_Tb AS VARCHAR) + '|' + CAST(Contadeb_Tb AS VARCHAR) [BancoConta], 0 [Produto], NULL, NULL FROM TransfBco INNER JOIN CCorrente ON Empresa_Tb = Empresa_Banco AND Contadeb_Tb = Conta_Banco AND BcoDeb_Tb = Numero_Banco WHERE Data_Tb BETWEEN <DataInicio> AND <DataTermino> UNION ALL SELECT  EmpresaCred_Tb [Empresa], 'DIVERSAS' [Obra], '' [Item], '' [CompPl_Des], '' [Descr_Comp], COALESCE(NULLIF(HistLancCred_Tb, ''), HistLanc_Tb) [Nominal], NULL [Fornecedor], NumDoc_Tb [NF], Valor_Tb [Valor], '' [Chave_Venda], Data_Tb [Vencimento], BcoCred_Tb [Banco], Agencia_Banco [Agencia], ContaCred_Tb [Conta], '' [Cheque], Data_Tb [Emissão], '' [Natureza], NULL [DtNF], '' [Processo], '' [Chave1], 'TRANSFERÊNCIA' [Origem], 0 [ValorNF], '' [TipoParc], CAST(BcoCred_Tb AS VARCHAR) + '|' + CAST(ContaCred_Tb AS VARCHAR) [BancoConta], 0 [Produto], NULL, NULL FROM TransfBco INNER JOIN CCorrente  ON EmpresaCred_Tb = Empresa_Banco AND Contacred_Tb = Conta_Banco AND Bcocred_Tb = Numero_Banco WHERE Data_Tb BETWEEN <DataInicio> AND <DataTermino> UNION ALL SELECT  Empresa_Crc [Empresa], Obra_Crc [Obra], '' [Item], CAST(IdProduto AS VARCHAR) [CompPl_Des], DescProduto [Descr_Comp], CAST(Cliente_Prc AS VARCHAR) [Nominal], NULL [Fornecedor], CAST(NumNfAux_Nf AS VARCHAR) [NF], SUM(ValParcela_Crc) * PorcProdVenda [Valor], '' [Chave_Venda], Data_Prc [Vencimento], '0' [Banco], '' [Agencia], '0' [Conta], '' [Cheque], DataPror_Prc [Emissao], '' [Natureza], DataEmis_Nf [DtNF], CAST(NumVend_Crc AS VARCHAR) + '-' + CAST(NumParc_Crc AS VARCHAR) [Processo], '' [Chave1], 'CONTAS RECEBER' [Origem], ValorTotNota_Nf [ValorNF], COALESCE(Descricao_Par, '') [TipoParc], '0|0' [BancoConta], 0 [Produto], NULL, NULL FROM ContasReceberCalc INNER JOIN ContasReceber ON Empresa_Crc = Empresa_Prc AND Obra_Crc = Obra_Prc AND NumVend_Crc = NumVend_Prc AND NumParc_Crc = NumParc_Prc AND Tipo_Crc = Tipo_Prc AND NumParcGer_Crc = NumParcGer_Prc LEFT JOIN Parcelas ON Tipo_Crc = Tipo_Par LEFT JOIN ( SELECT  EmpresaNf_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END [NumNfAux_Nf], ObraVen_Vnv, MAX(DataEmis_Nf) [DataEmis_Nf], NumVen_Vnv, SUM(ValorTotNota_Nf) [ValorTotNota_Nf] FROM NotasFiscais INNER JOIN VinculoNotaVenda ON Empresa_Nf = EmpresaNf_Vnv AND Num_Nf = NumNf_Vnv INNER JOIN ( SELECT  EmpresaNf_Vnv [Empresa], ObraVen_Vnv [Obra], NumVen_Vnv [Venda], COUNT(NumNf_Vnv) [Cont] FROM VinculoNotaVenda GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv ) [NotasVenda] ON Empresa = EmpresaNf_Vnv AND Obra = ObraVen_Vnv AND Venda = NumVen_Vnv GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END ) [NotasF] ON Empresa_Crc = EmpresaNf_Vnv AND NumVend_Crc = NumVen_Vnv AND Obra_Crc = ObraVen_Vnv INNER JOIN ( SELECT  Empresa_Ven, Obra_Ven, Num_Ven, Produto_Itv [IdProduto], Descricao_Psc [DescProduto], ((Qtde_Itv * PrecoProc_Itv) - ValComissaoDir_Itv) / ValorTot_Ven [PorcProdVenda] FROM Vendas INNER JOIN ItensVenda ON Empresa_Ven = Empresa_Itv AND Obra_Ven = Obra_Itv AND Num_Ven = NumVend_Itv INNER JOIN PrdSrv ON NumProd_Psc = Produto_Itv WHERE ValorTot_Ven > 0 ) [ProdVenda] ON Empresa_Crc = Empresa_Ven AND NumVend_Crc = Num_Ven AND Obra_Crc = Obra_Ven WHERE Data_Prc BETWEEN <DataInicio> AND <DataTermino> GROUP BY Empresa_Crc, Obra_Crc, Cliente_Prc, Descricao_Par, Data_Prc, DataPror_Prc, NumVend_Crc, NumParc_Crc, NumNfAux_Nf, IdProduto, DescProduto, PorcProdVenda, NumNfAux_Nf, DataEmis_Nf, ValorTotNota_Nf UNION ALL SELECT  Empresa_Rec [Empresa], Obra_Rec [Obra], '' [Item], CAST(IdProduto AS VARCHAR) [CompPl_Des], DescProduto [Descr_Comp], CAST(Cliente_Rec AS VARCHAR) [Nominal], NULL [Fornecedor], CAST(NumNfAux_Nf AS VARCHAR) [NF], SUM(PercentValor_Rpd) * PorcProdVenda [Valor], CAST(NumCont_Rpd AS VARCHAR) + '_' + CAST(Tipo_Rpg AS VARCHAR) + '_' + CAST(NumReceb_Rpg AS VARCHAR) [Chave_Venda], DataVenci_Rec [Vencimento], BancoDep_Rpg [Banco], AgenciaDep_Rpg [Agencia], ContaDep_Rpg [Conta], '' [Cheque], Data_Rec [Emissao], '' [Natureza], DataEmis_Nf [DtNF], CAST(NumVend_Rec AS VARCHAR) + '-' + CAST(NumParc_Rec AS VARCHAR) [Processo], '' [Chave1], 'RECEBIDAS' [Origem], ValorTotNota_Nf [ValorNF], ISNULL(Descricao_Par, '') [TipoParc], CAST(BancoDep_Rpg AS VARCHAR) + '|' + CAST(ContaDep_Rpg AS VARCHAR), 0 [Produto], NULL, NULL FROM Recebidas INNER JOIN RecebePgtoDiv ON Empresa_Rec = Empresa_Rpd AND NumVend_Rec = NumVend_Rpd AND Obra_Rec = Obra_Rpd AND NumParc_Rec = NumParc_Rpd AND ParcType_Rec = ParcType_Rpd AND Tipo_Rec = Tipo_Rpd AND NumParcGer_Rec = NumParcGer_Rpd LEFT JOIN Parcelas ON Tipo_Rec = Tipo_Par INNER JOIN RecebePgto ON Empresa_Rpd = Empresa_Rpg AND NumReceb_Rpd = NumReceb_Rpg AND NumCont_Rpd = NumCont_Rpg AND TipoRpg_Rpd = Tipo_Rpg INNER JOIN Bancos ON BancoDep_Rpg = Numero_Banco LEFT JOIN ( SELECT  EmpresaNf_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END [NumNfAux_Nf], ObraVen_Vnv, MAX(DataEmis_Nf) [DataEmis_Nf], NumVen_Vnv, SUM(ValorTotNota_Nf) [ValorTotNota_Nf] FROM NotasFiscais INNER JOIN VinculoNotaVenda ON Empresa_Nf = EmpresaNf_Vnv AND Num_Nf = NumNf_Vnv INNER JOIN ( SELECT  EmpresaNf_Vnv [Empresa], ObraVen_Vnv [Obra], NumVen_Vnv [Venda], COUNT(NumNf_Vnv) [Cont] FROM VinculoNotaVenda GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv ) [NotasVenda] ON EmpresaNf_Vnv = Empresa AND ObraVen_Vnv = Obra AND NumVen_Vnv = Venda GROUP BY EmpresaNf_Vnv, ObraVen_Vnv, NumVen_Vnv, CASE WHEN Cont = 1 THEN NumNfAux_Nf ELSE 'VÁRIOS DOCS' END ) [NotasF] ON EmpresaNf_Vnv = Empresa_Rec AND NumVen_Vnv = NumVend_Rec AND ObraVen_Vnv = Obra_Rec INNER JOIN ( SELECT  Empresa_VRec, Obra_VRec, Num_VRec, Produto_Itr [IdProduto], Descricao_Psc [DescProduto], ((Qtde_Itr * PrecoProc_Itr) - ValComissaoDir_Itr) / ValorTot_VRec [PorcProdVenda] FROM VendasRecebidas INNER JOIN ItensRecebidas ON Empresa_VRec = Empresa_Itr AND Obra_VRec = Obra_Itr AND Num_VRec = NumVend_Itr INNER JOIN PrdSrv ON NumProd_Psc = Produto_Itr WHERE ValorTot_VRec > 0 ) [ProdVenda] ON Empresa_Rec = Empresa_VRec AND NumVend_Rec = Num_VRec AND Obra_Rec = Obra_VRec WHERE Data_Rec BETWEEN <DataInicio> AND <DataTermino> GROUP BY Empresa_Rec, Obra_Rec, Cliente_Rec, NumCont_Rpd, Tipo_Rpg, NumReceb_Rpg, DataVenci_Rec, BancoDep_Rpg, AgenciaDep_Rpg, ContaDep_Rpg, Data_Rec, NumVend_Rec, NumParc_Rec, Descricao_Par, NumNfAux_Nf, IdProduto, DescProduto, PorcProdVenda, NumNfAux_Nf, DataEmis_Nf, ValorTotNota_Nf ) [Movimentacao] LEFT JOIN Pessoas [Nominal] ON CASE WHEN(ISNUMERIC(Movimentacao.Nominal) = 1) THEN CAST(Movimentacao.Nominal AS INT) ELSE NULL END = Nominal.Cod_Pes LEFT JOIN Pessoas [Fornecedor] ON Movimentacao.Fornecedor = Fornecedor.Cod_Pes INNER JOIN ( SELECT Item [ItemBC] FROM Fn_SplitForTable('<<LISTA_CONTAS>>',',') UNION SELECT '0|0' ) [TabBanco] ON Movimentacao.BancoConta = TabBanco.ItemBC INNER JOIN ( SELECT DISTINCT Empresa [Emp], Obra [Obr] FROM (SELECT Empresa_Obr [Empresa], Cod_Obr [Obra] FROM Obras WHERE Empresa_Obr BETWEEN 1 AND 45 AND Empresa_Obr NOT IN (4,34,35,36,37,38)) [LEO] UNION SELECT DISTINCT Empresa [Emp], 'DIVERSAS' [Obr] FROM (SELECT Empresa_Obr [Empresa], Cod_Obr [Obra] FROM Obras WHERE Empresa_Obr BETWEEN 1 AND 45 AND Empresa_Obr NOT IN (4,34,35,36,37,38)) [LEO] ) [EmpObr] ON Movimentacao.Empresa = EmpObr.Emp AND Movimentacao.Obra = EmpObr.Obr LEFT JOIN PrdSrv ON ProdutoPl_Des = PrdSrv.NumProd_Psc LEFT JOIN Empresas ON Movimentacao.Empresa = Empresas.Codigo_Emp LEFT JOIN Obras ON Movimentacao.Empresa = Obras.Empresa_Obr AND Movimentacao.Obra = Obras.Cod_Obr ORDER BY Movimentacao.Empresa, Movimentacao.Obra, Movimentacao.Origem, Movimentacao.Vencimento END